def resolve_entity(address: str) -> Optional[EntityInfo]:
    """Look up an address in the entity registry."""
    if not address:
        return None
    data = KNOWN_ENTITIES.get(address)
    if data:
        return EntityInfo(**data)
    return None

def is_cex(address: str) -> bool:
    info = resolve_entity(address)
    return info is not None and info.category == "CEX"

import uvicorn
from fastapi import FastAPI, HTTPException, Query
from fastapi.middleware.cors import CORSMiddleware
from typing import Optional, List, Dict, Any
from pydantic import BaseModel

from crawler import discover_genesis_funder, get_wallet_balance
from profiler import get_wallet_profile
from flow_engine import build_wallet_graph, detect_behavioral_clusters
from registry import KNOWN_ENTITIES, resolve_entity

app = FastAPI(
    title="SolForensics Engine API",
    description="Solana Wallet Intelligence & Fund Flow Forensics Platform",
    version="1.0.0"
)

# Enable CORS for local frontend development
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.get("/api/health")
async def health_check():
    return {
        "status": "healthy",
        "service": "SolForensics Core Engine",
        "registered_entities_count": len(KNOWN_ENTITIES)
    }

@app.get("/api/wallet/{address}/profile")
async def wallet_profile(address: str, tx_limit: int = Query(50, ge=1, le=200)):
    """Fetch complete financial dossier, counterparties, protocol exposure, and CEX interactions."""
    try:
        profile = await get_wallet_profile(address, tx_limit=tx_limit)
        return profile
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/wallet/{address}/origin")
async def wallet_origin(address: str):
    """
    Autonomously crawl backwards through signatures to discover the original genesis funder,
    creation transaction, and initial capital.
    """
    try:
        origin_data = await discover_genesis_funder(address)
        return origin_data
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/wallet/{address}/graph")
async def wallet_graph(
    address: str, 
    limit: int = Query(50, ge=5, le=100),
    min_amount: float = Query(0.001, ge=0.0)
):
    """Returns React Flow compatible nodes and edges for canvas visualization."""
    try:
        graph = await build_wallet_graph(address, limit=limit, min_amount_sol=min_amount)
        return graph
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/wallet/{address}/clusters")
async def wallet_clusters(address: str, tx_limit: int = Query(100, ge=10, le=200)):
    """Detect forensic behavioral patterns (dispensers, peel chains, consolidation)."""
    try:
        clusters = await detect_behavioral_clusters(address, tx_limit=tx_limit)
        return clusters
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/entities")
async def list_entities(category: Optional[str] = None):
    """List or filter known CEX, DEX, and protocol entities in registry."""
    results = []
    for addr, data in KNOWN_ENTITIES.items():
        if category and data.get("category") != category.upper():
            continue
        results.append({
            "address": addr,
            **data
        })
    return {"entities": results, "total": len(results)}

if __name__ == "__main__":
    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=True)

