                        isHigh
                          ? 'bg-rose-500/10 text-rose-400 border border-rose-500/30'
                          : isMedium
                          ? 'bg-amber-500/10 text-amber-400 border border-amber-500/30'
                          : 'bg-blue-500/10 text-blue-400 border border-blue-500/30'
                      }`}
                    >
                      {c.confidence} CONFIDENCE
                    </span>
                  </div>
                  <p className="text-xs text-slate-300 leading-relaxed mb-3">{c.details}</p>
                </div>

                <div className="pt-2 border-t border-border/60 flex items-center justify-between text-[11px] text-slate-500 font-mono">
                  <span>Heuristic Scanner</span>
                  {c.counterparties_count && (
                    <span className="text-slate-300">
                      {c.counterparties_count} Counterparties Involved
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { WalletOverview } from './components/WalletOverview';
import { GenesisOriginCard } from './components/GenesisOriginCard';
import { GraphCanvas } from './components/GraphCanvas';
import { CounterpartiesTable } from './components/CounterpartiesTable';
import { CexExposureView } from './components/CexExposureView';
import { BehavioralClustersView } from './components/BehavioralClustersView';
import { WalletProfile, GenesisOrigin, GraphPayload, BehavioralCluster } from './types';
import { Network, FileText, Compass, Building2, Cpu, AlertCircle, RefreshCw, Filter } from 'lucide-react';

export const App: React.FC = () => {
  const [activeAddress, setActiveAddress] = useState<string>('CoyUhkGh8LiWaw82sp2TBD9jvvPy8d9rbmUa6G6upGoY');
  const [activeTab, setActiveTab] = useState<'graph' | 'profile' | 'origin' | 'cex' | 'clusters'>('graph');

  // Data states
  const [profile, setProfile] = useState<WalletProfile | null>(null);
  const [origin, setOrigin] = useState<GenesisOrigin | null>(null);
  const [graphData, setGraphData] = useState<GraphPayload | null>(null);
  const [clusters, setClusters] = useState<BehavioralCluster[]>([]);

  // Loading states
  const [loadingProfile, setLoadingProfile] = useState<boolean>(false);
  const [loadingOrigin, setLoadingOrigin] = useState<boolean>(false);
  const [loadingGraph, setLoadingGraph] = useState<boolean>(false);
  const [loadingClusters, setLoadingClusters] = useState<boolean>(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Filter states
  const [minAmount, setMinAmount] = useState<number>(0.001);

  const fetchAllData = async (address: string) => {
    setErrorMsg(null);
    const cleanAddr = address.trim();
    if (!cleanAddr) return;

    // 1. Fetch Profile
    setLoadingProfile(true);
    fetch(`/api/wallet/${cleanAddr}/profile?tx_limit=60`)
      .then((res) => {
        if (!res.ok) throw new Error(`Profile fetch failed: ${res.statusText}`);
        return res.json();
      })
      .then((data) => setProfile(data))
      .catch((err) => setErrorMsg(err.message))
      .finally(() => setLoadingProfile(false));

    // 2. Fetch Origin (Genesis Funder)
    setLoadingOrigin(true);
    fetch(`/api/wallet/${cleanAddr}/origin`)
      .then((res) => res.json())
      .then((data) => setOrigin(data))
      .catch((err) => console.error('Origin error:', err))
      .finally(() => setLoadingOrigin(false));

    // 3. Fetch Graph
    setLoadingGraph(true);
    fetch(`/api/wallet/${cleanAddr}/graph?limit=50&min_amount=${minAmount}`)
      .then((res) => res.json())
      .then((data) => setGraphData(data))
      .catch((err) => console.error('Graph error:', err))
      .finally(() => setLoadingGraph(false));

    // 4. Fetch Clusters
    setLoadingClusters(true);
    fetch(`/api/wallet/${cleanAddr}/clusters?tx_limit=60`)
      .then((res) => res.json())
      .then((data) => setClusters(data.patterns_detected || []))
      .catch((err) => console.error('Clusters error:', err))
      .finally(() => setLoadingClusters(false));
  };

  useEffect(() => {
    fetchAllData(activeAddress);
  }, [activeAddress]);

  const handleSearch = (address: string) => {
    setActiveAddress(address);
  };

  const isGlobalLoading = loadingProfile && !profile;

  return (
    <div className="min-h-screen flex flex-col bg-[#080c14] text-slate-100">
      {/* Top Navigation */}
      <Header
        onSearch={handleSearch}
        loading={loadingProfile || loadingGraph}
        activeAddress={activeAddress}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 py-6 space-y-6">
        {/* Error Banner */}
        {errorMsg && (
          <div className="bg-rose-500/10 border border-rose-500/30 rounded-xl p-4 flex items-center gap-3 text-rose-300 text-sm font-mono">
            <AlertCircle className="w-5 h-5 shrink-0 text-rose-400" />
            <span>{errorMsg}</span>
          </div>
        )}

        {/* Global Wallet Overview Dossier */}
        {profile && <WalletOverview profile={profile} />}

        {/* Navigation Tabs */}
        <div className="border-b border-border flex items-center justify-between gap-4 overflow-x-auto">
          <div className="flex items-center gap-1">
            <button
              onClick={() => setActiveTab('graph')}
              className={`flex items-center gap-2 px-4 py-3 text-xs md:text-sm font-medium border-b-2 transition -mb-[1px] ${
                activeTab === 'graph'
                  ? 'border-[#14F195] text-[#14F195]'
                  : 'border-transparent text-slate-400 hover:text-slate-200'
              }`}
            >
              <Network className="w-4 h-4" />
              <span>Relationship Graph</span>
              {graphData && (
                <span className="text-[10px] bg-slate-800 px-1.5 py-0.5 rounded font-mono text-slate-400">
                  {graphData.nodes.length} nodes
                </span>
              )}
            </button>

            <button
              onClick={() => setActiveTab('origin')}
              className={`flex items-center gap-2 px-4 py-3 text-xs md:text-sm font-medium border-b-2 transition -mb-[1px] ${
                activeTab === 'origin'
                  ? 'border-[#14F195] text-[#14F195]'
                  : 'border-transparent text-slate-400 hover:text-slate-200'
              }`}
            >
              <Compass className="w-4 h-4" />
              <span>Fund Origin Analysis</span>
              {origin?.status === 'SUCCESS' && (
                <span className="w-2 h-2 rounded-full bg-emerald-400" />
              )}
            </button>

            <button
              onClick={() => setActiveTab('profile')}
              className={`flex items-center gap-2 px-4 py-3 text-xs md:text-sm font-medium border-b-2 transition -mb-[1px] ${
                activeTab === 'profile'
                  ? 'border-[#14F195] text-[#14F195]'
                  : 'border-transparent text-slate-400 hover:text-slate-200'
              }`}
            >
              <FileText className="w-4 h-4" />
              <span>Counterparty Matrix</span>
            </button>

            <button
              onClick={() => setActiveTab('cex')}
              className={`flex items-center gap-2 px-4 py-3 text-xs md:text-sm font-medium border-b-2 transition -mb-[1px] ${
                activeTab === 'cex'
                  ? 'border-[#14F195] text-[#14F195]'
                  : 'border-transparent text-slate-400 hover:text-slate-200'
              }`}
            >
              <Building2 className="w-4 h-4" />
              <span>CEX Exposure</span>
              {profile && profile.cex_exposure.interactions_count > 0 && (
                <span className="text-[10px] bg-amber-500/20 text-amber-300 px-1.5 py-0.5 rounded font-mono">
                  {profile.cex_exposure.interactions_count}
                </span>
              )}
            </button>

            <button
              onClick={() => setActiveTab('clusters')}
              className={`flex items-center gap-2 px-4 py-3 text-xs md:text-sm font-medium border-b-2 transition -mb-[1px] ${
                activeTab === 'clusters'
                  ? 'border-[#14F195] text-[#14F195]'
                  : 'border-transparent text-slate-400 hover:text-slate-200'
              }`}
            >
              <Cpu className="w-4 h-4" />
              <span>Behavioral Clusters</span>
              {clusters.length > 0 && (
                <span className="text-[10px] bg-purple-500/20 text-purple-300 px-1.5 py-0.5 rounded font-mono">
                  {clusters.length}
                </span>
              )}
            </button>
          </div>

          <button
            onClick={() => fetchAllData(activeAddress)}
            disabled={loadingProfile || loadingGraph}
            className="p-1.5 rounded-lg border border-border hover:bg-slate-800 text-slate-400 hover:text-slate-200 transition shrink-0"
            title="Refresh Analysis"
          >
            <RefreshCw className={`w-4 h-4 ${loadingProfile || loadingGraph ? 'animate-spin' : ''}`} />
          </button>
        </div>

        {/* Tab Panels */}
        {isGlobalLoading ? (
          <div className="bg-[#111827] border border-border rounded-xl p-16 flex flex-col items-center justify-center gap-4 text-slate-400">
            <div className="w-8 h-8 border-3 border-[#14F195] border-t-transparent rounded-full animate-spin" />
            <div className="text-center font-mono text-sm">
              <p className="text-slate-200 font-semibold mb-1">Deconstructing On-Chain Transactions</p>
              <p className="text-xs text-slate-500">Querying Helius RPC, decoding transfers, and mapping counterparties...</p>
            </div>
          </div>
        ) : (
          <div>
            {activeTab === 'graph' && (
              <div className="space-y-4">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs text-slate-400 bg-[#111827] p-3 rounded-lg border border-border">
                  <span className="font-mono">
                    Showing top interactions across latest {profile?.activity.sampled_transactions_count || 50} transactions. Click any node to inspect.
                  </span>
                  <div className="flex items-center gap-2">
                    <Filter className="w-3.5 h-3.5 text-slate-500" />
                    <span>Min Transfer:</span>
                    <select
                      value={minAmount}
                      onChange={(e) => {
                        const val = parseFloat(e.target.value);
                        setMinAmount(val);
                        fetch(`/api/wallet/${activeAddress}/graph?limit=50&min_amount=${val}`)
                          .then((res) => res.json())
                          .then((data) => setGraphData(data));
                      }}
                      className="bg-[#0b101a] border border-border rounded px-2 py-1 text-slate-200 font-mono outline-none"
                    >
                      <option value="0.0">All Transfers (Including dust)</option>
                      <option value="0.001">≥ 0.001 SOL</option>
                      <option value="0.01">≥ 0.01 SOL</option>
                      <option value="0.1">≥ 0.1 SOL</option>
                      <option value="1.0">≥ 1.0 SOL</option>
                    </select>
                  </div>
                </div>

                {loadingGraph ? (
                  <div className="h-[620px] bg-[#080c14] border border-border rounded-xl flex items-center justify-center gap-3 text-slate-400 font-mono text-xs">
                    <div className="w-5 h-5 border-2 border-[#14F195] border-t-transparent rounded-full animate-spin" />
                    <span>Synthesizing relationship graph...</span>
                  </div>
                ) : graphData ? (
                  <GraphCanvas
                    nodes={graphData.nodes as any}
                    edges={graphData.edges as any}
                    onNodeClick={(nodeId) => {
                      if (nodeId !== activeAddress) {
                        setActiveAddress(nodeId);
                      }
                    }}
                  />
                ) : null}
              </div>
            )}

            {activeTab === 'origin' && (
              <div className="space-y-6">
                <GenesisOriginCard
                  origin={origin}
                  loading={loadingOrigin}
                  onExploreAddress={(addr) => setActiveAddress(addr)}
                />

                {/* Explanatory notes */}
                <div className="bg-[#111827] border border-border rounded-xl p-5 text-xs text-slate-400 leading-relaxed">
                  <h4 className="font-bold text-slate-200 mb-2 font-mono">Why Initial Funder Analysis Matters</h4>
                  <p className="mb-2">
                    When bot operators, drainers, or sybil farm creators launch new wallets, they must fund them with initial SOL to pay the account rent exemption and transaction fees.
                  </p>
                  <p>
                    By identifying the address that first injected capital into this wallet, you can uncover master distributor wallets, upstream exchange withdrawal accounts, or common puppet masters linking seemingly independent on-chain actors.
                  </p>
                </div>
              </div>
            )}

            {activeTab === 'profile' && profile && (
              <CounterpartiesTable
                topInbound={profile.top_inbound_counterparties}
                topOutbound={profile.top_outbound_counterparties}
                protocolExposure={profile.protocol_exposure}
                onInspect={(addr) => setActiveAddress(addr)}
              />
            )}

            {activeTab === 'cex' && profile && (
              <CexExposureView
                cexData={profile.cex_exposure}
                walletAddress={activeAddress}
              />
            )}

            {activeTab === 'clusters' && (
              <BehavioralClustersView
                clusters={clusters}
                loading={loadingClusters}
                walletAddress={activeAddress}
              />
            )}
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-border bg-[#090d16] py-4 text-center text-xs text-slate-500 font-mono">
        SolForensics Engine • Powered by Helius RPC & Autonomous On-Chain Traversal • Mainnet Beta
      </footer>
    </div>
  );
};

export default App;

