import React, { useMemo } from 'react';
import {
  ReactFlow,
  Controls,
  Background,
  MiniMap,
  Handle,
  Position,
  NodeProps,
  Node,
  Edge,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { GraphNodeData } from '../types';
import { Building2, Wallet, ArrowDownLeft, ArrowUpRight, Zap } from 'lucide-react';

// Custom Target Node (Center of investigation)
const TargetNodeComponent: React.FC<NodeProps> = (props) => {
  const data = props.data as unknown as GraphNodeData;
  return (
    <div className="bg-[#111827] border-2 border-[#14F195] shadow-xl shadow-[#14F195]/20 rounded-xl p-3 min-w-[200px] text-slate-100">
      <Handle type="target" position={Position.Left} className="w-2.5 h-2.5 !bg-[#14F195]" />
      <div className="flex items-center gap-2 mb-1.5">
        <div className="w-6 h-6 rounded bg-[#14F195]/20 flex items-center justify-center text-[#14F195]">
          <Zap className="w-3.5 h-3.5" />
        </div>
        <span className="text-[11px] font-mono uppercase tracking-wider text-[#14F195] font-bold">
          Target Wallet
        </span>
      </div>
      <div className="font-mono text-xs font-semibold truncate text-white" title={data.full_address}>
        {data.label}
      </div>
      <div className="mt-2 pt-2 border-t border-border flex items-center justify-between text-[11px] text-slate-400 font-mono">
        <span className="text-emerald-400">+{data.inflow?.toFixed(2) || '0.00'}</span>
        <span className="text-rose-400">-{data.outflow?.toFixed(2) || '0.00'}</span>
      </div>
      <Handle type="source" position={Position.Right} className="w-2.5 h-2.5 !bg-[#14F195]" />
    </div>
  );
};

// Custom Entity/Counterparty Node (Left & Right tiers)
const EntityNodeComponent: React.FC<NodeProps> = (props) => {
  const data = props.data as unknown as GraphNodeData;
  const isCex = data.is_cex || data.category === 'CEX';
  const isDex = data.category === 'DEX';

  let borderColor = 'border-border';
  let badgeColor = 'bg-slate-800 text-slate-300';

  if (isCex) {
    borderColor = 'border-amber-500/60 shadow-lg shadow-amber-500/10';
    badgeColor = 'bg-amber-500/10 text-amber-300 border border-amber-500/30';
  } else if (isDex) {
    borderColor = 'border-purple-500/60 shadow-lg shadow-purple-500/10';
    badgeColor = 'bg-purple-500/10 text-purple-300 border border-purple-500/30';
  }

  return (
    <div className={`bg-[#0f172a] border ${borderColor} rounded-xl p-3 min-w-[190px] text-slate-100`}>
      <Handle type="target" position={Position.Left} className="w-2 h-2 !bg-purple-400" />
      <div className="flex items-center justify-between gap-2 mb-1">
        <div className="flex items-center gap-1.5">
          {isCex ? (
            <Building2 className="w-3.5 h-3.5 text-amber-400" />
          ) : (
            <Wallet className="w-3.5 h-3.5 text-slate-400" />
          )}
          <span className="text-xs font-bold text-slate-200 truncate max-w-[110px]" title={data.label}>
            {data.label}
          </span>
        </div>
        <span className={`text-[9px] px-1.5 py-0.5 rounded font-mono font-medium ${badgeColor}`}>
          {data.category}
        </span>
      </div>

      <div className="font-mono text-[10px] text-slate-400 truncate" title={data.full_address}>
        {data.full_address}
      </div>

      <div className="mt-2 pt-1.5 border-t border-border/60 flex items-center justify-between text-[10px] font-mono text-slate-400">
        {data.outflow > 0 && (
          <span className="text-emerald-400 flex items-center gap-0.5">
            <ArrowUpRight className="w-3 h-3" /> {data.outflow.toFixed(2)} SOL
          </span>
        )}
        {data.inflow > 0 && (
          <span className="text-rose-400 flex items-center gap-0.5">
            <ArrowDownLeft className="w-3 h-3" /> {data.inflow.toFixed(2)} SOL
          </span>
        )}
      </div>
      <Handle type="source" position={Position.Right} className="w-2 h-2 !bg-emerald-400" />
    </div>
  );
};

interface GraphCanvasProps {
  nodes: Node[];
  edges: Edge[];
  onNodeClick?: (nodeId: string) => void;
}

export const GraphCanvas: React.FC<GraphCanvasProps> = ({ nodes, edges, onNodeClick }) => {
  const nodeTypes = useMemo(
    () => ({
      targetNode: TargetNodeComponent,
      entityNode: EntityNodeComponent,
    }),
    []
  );

  return (
    <div className="w-full h-[620px] bg-[#080c14] border border-border rounded-xl relative overflow-hidden">
      <div className="absolute top-3 left-4 z-10 flex items-center gap-4 bg-[#111827]/80 backdrop-blur border border-border px-3 py-1.5 rounded-lg text-xs font-mono text-slate-400">
        <span className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-purple-400 inline-block" /> Inbound Sources (Left)
        </span>
        <span className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-[#14F195] inline-block" /> Target (Center)
        </span>
        <span className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-emerald-400 inline-block" /> Outbound Destinations (Right)
        </span>
      </div>

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        fitView
        onNodeClick={(_, node) => onNodeClick && onNodeClick(node.id)}
      >
        <Background color="#1e293b" gap={20} size={1} />
        <Controls />
        <MiniMap
          nodeStrokeColor="#14F195"
          nodeColor="#1e293b"
          maskColor="rgba(8, 12, 20, 0.7)"
        />
      </ReactFlow>
    </div>
  );
};
